parameters.jsCode:
/**
 * TRIDENGUARD: Deterministic Validator v3.2
 * Role: Senior AI Engineer / Neuro-symbolic Logic
 * Objetivo: Implementación de las 8 Reglas Atómicas de Exclusión (R1-R8).
 */

for (const item of $input.all()) {
  const output = item.json.output || {};
  const radicals = Array.isArray(output.radicals) ? output.radicals : [];
  const types = new Set(radicals.map(r => r.radical));
  const original_text = $("Frontend Webhook").item.json.body?.text || "";

  let errors = [];

  // R1: Sujeto sin Acción (Actor/Deontic presente, pero falta Acción)
  if ((types.has('Actor') || types.has('Deontic')) && !types.has('Action')) {
      errors.push('R1_SUJETO_SIN_ACCION');
  }

  // R2: Acción sin Sujeto
  if (types.has('Action') && !types.has('Actor')) {
      errors.push('R2_ACCION_SIN_SUJETO');
  }

  // R3: Objeto sin Referente (Objeto sin Actor ni Acción)
  if (types.has('Object') && !types.has('Actor') && !types.has('Action')) {
      errors.push('R3_OBJETO_SIN_REFERENTE');
  }

  // R4: Métrica Huérfana (Métrica sin Actor ni Objeto)
  if (types.has('Metric') && !types.has('Actor') && !types.has('Object')) {
      errors.push('R4_METRICA_HUERFANA');
  }

  // R5: Condición sin Gatillo (Condición sin Acción)
  if (types.has('Condition') && !types.has('Action')) {
      errors.push('R5_CONDICION_SIN_GATILLO');
  }

  // R6: Temporal sin Anclaje (Temporal sin Actor ni Acción)
  if (types.has('Temporal') && !types.has('Actor') && !types.has('Action')) {
      errors.push('R6_TEMPORAL_SIN_ANCLAJE');
  }

  // R7: Espacial Inerte (Espacial sin Actor ni Acción)
  if (types.has('Spatial') && !types.has('Actor') && !types.has('Action')) {
      errors.push('R7_ESPACIAL_INERTE');
  }

  // R8: Deóntico sin Conducta (Deóntico sin Acción)
  if (types.has('Deontic') && !types.has('Action')) {
      errors.push('R8_DEONTICO_SIN_CONDUCTA');
  }

  // Validación Global
  const is_valid = errors.length === 0 && radicals.length >= 2 && output.axiom?.length > 5;

  item.json = {
    case_id: crypto.randomUUID(),
    timestamp: new Date().toISOString(),
    status: is_valid ? 'VALIDATED' : 'QUARANTINED',
    rejection_reason: errors.length > 0 ? errors.join(', ') : (radicals.length < 2 ? 'INSUFFICIENT_DENSITY' : 'NONE'),
    and_gate_ok: is_valid,
    trident_status: `${output.axiom?.length > 5 ? '✓' : '✗'}${radicals.length >= 2 ? '✓' : '✗'}${errors.length === 0 ? '✓' : '✗'}`,
    radicals_extracted: radicals.length,
    axiom: output.axiom,
    radicals_json: JSON.stringify(radicals),
    original_text
  };
}

return $input.all();

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "axiom": {
      "type": "string",
      "description": "Hecho o cláusula fundamental extraída de forma concisa."
    },
    "radicals": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "radical": {
            "type": "string",
            "enum": [
              "Actor",
              "Deontic",
              "Action",
              "Object",
              "Temporal",
              "Spatial",
              "Metric",
              "Condition"
            ]
          },
          "value": {
            "type": "string"
          }
        },
        "required": [
          "radical",
          "value"
        ]
      },
      "minItems": 2
    }
  },
  "required": [
    "axiom",
    "radicals"
  ]
}

